import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

reverse_cumsum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template<typename scalar_t>
__global__ void reverse_cumsum_kernel(const scalar_t* input, scalar_t* output, int dim_size, int num_rows) {
    const int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row >= num_rows) return;

    const scalar_t* row_in = input + row * dim_size;
    scalar_t* row_out = output + row * dim_size;

    scalar_t sum = 0;
    for (int i = dim_size - 1; i >= 0; --i) {
        sum += row_in[i];
        row_out[i] = sum;
    }
}

torch::Tensor reverse_cumsum_cuda(torch::Tensor input, int dim) {
    auto input_2d = input.flatten(0, dim-1).view({-1, input.size(dim)});
    int num_rows = input_2d.size(0);
    int dim_size = input_2d.size(1);

    auto output = torch::zeros_like(input_2d);

    const int threads = 256;
    const int blocks = (num_rows + threads - 1) / threads;

    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "reverse_cumsum", ([&] {
        reverse_cumsum_kernel<scalar_t><<<blocks, threads>>>(
            input_2d.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            dim_size,
            num_rows
        );
    }));

    return output.view(input.sizes());
}
"""

reverse_cumsum_cpp = "torch::Tensor reverse_cumsum_cuda(torch::Tensor input, int dim);"

reverse_cumsum = load_inline(
    name="reverse_cumsum",
    cpp_sources=reverse_cumsum_cpp,
    cuda_sources=reverse_cumsum_source,
    functions=["reverse_cumsum_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.dim = dim

    def forward(self, x):
        return reverse_cumsum.reverse_cumsum_cuda(x, self.dim)
